    private static float[] decode(String[] chunks) {
        String hex = String.join("", chunks);
        float[] table = new float[hex.length() / 8];
        for (int i = 0; i < table.length; i++) {
            table[i] = Float.intBitsToFloat(Integer.parseUnsignedInt(hex, i * 8, i * 8 + 8, 16));
        }
        return table;
    }
